#include "stdlib/stats/base/dists/hypergeometric/cdf.h"
#include "stdlib/stats/base/dists/hypergeometric/pmf.h"
#include "stdlib/math/base/assert/is_nan.h"
#include "stdlib/math/base/assert/is_nonnegative_integer.h"
#include "stdlib/math/base/assert/is_infinite.h"
#include "stdlib/math/base/special/trunc.h"
#include "stdlib/math/base/special/max.h"
#include "stdlib/math/base/special/min.h"

/**
* Evaluates the cumulative distribution function (CDF) for a hypergeometric distribution.
*
* @param x    input value
* @param N    population size
* @param K    subpopulation size
* @param n    number of draws
* @return     evaluated CDF
*
* @example
* double y = stdlib_base_dists_hypergeometric_cdf( 1.0, 8, 4, 2 );
* // returns ~0.786
*/
double stdlib_base_dists_hypergeometric_cdf(
	const double x,
	const double N,
	const double K,
	const double n
) {
	double p;
	double ret;
	double denom;
	double num;
	int32_t i;
	int32_t upper;
	int32_t lower;
	int32_t xi;
	int32_t Ni, Ki, ni;

	if (
		stdlib_base_is_nan( x ) ||
		stdlib_base_is_nan( N ) ||
		stdlib_base_is_nan( K ) ||
		stdlib_base_is_nan( n ) ||
		stdlib_base_is_infinite( N ) ||
		stdlib_base_is_infinite( K ) ||
		stdlib_base_is_infinite( n ) ||
		!stdlib_base_is_nonnegative_integer( N ) ||
		!stdlib_base_is_nonnegative_integer( K ) ||
		!stdlib_base_is_nonnegative_integer( n ) ||
		K > N ||
		n > N
	) {
		return 0.0/0.0;
	}

	// Convert to integers after validation
	Ni = (int32_t)N;
	Ki = (int32_t)K;
	ni = (int32_t)n;
	xi = (int32_t)stdlib_base_trunc( x );

	lower = stdlib_base_max( 0, ni+Ki-Ni );
	upper = stdlib_base_min( ni, Ki );

	if ( xi < lower ) {
		return 0.0;
	}
	if ( xi >= upper ) {
		return 1.0;
	}

	p = stdlib_base_dists_hypergeometric_pmf( xi, Ni, Ki, ni );
	ret = p;

	for ( i = xi-1; i >= lower; i-- ) {
		num = ( i+1 ) * ( Ni-Ki-(ni-i-1) );
		denom = ( Ki-i ) * ( ni-i );
		p = ( num/denom ) * p;
		ret += p;
	}

	return stdlib_base_min( ret, 1.0 );
}
